    def __call__(self, x, weight, bias=None):
        """
        x      : torch.Tensor (B, C, H, W)  dtype=float16
        weight : torch.Tensor (C, K, K)    dtype=float16
        bias   : torch.Tensor (C,)        dtype=float16 (optional, only if self.bias is True)
        Returns torch.Tensor (B, C, H_out, W_out) dtype=float16
        """
        import torch

        B, C, H, W = x.shape
        K = self.k
        out_h = (H + 2 * self.padding - K) // self.stride + 1
        out_w = (W + 2 * self.padding - K) // self.stride + 1

        out = torch.empty((B, C, out_h, out_w), dtype=torch.float16, device=x.device)

        # Arguments for the PTX kernel (order must match the .param list)
        args = [
            out.data_ptr(),
            x.data_ptr(),
            weight.data_ptr(),
            B, C, H, W, out_h, out_w, K, self.stride, self.padding
        ]

        total_elements = B * C * out_h * out_w
        block_dim = (256, 1, 1)
        grid_dim = ((total_elements + 255) // 256, 1, 1)

        ptx_launch(self.module, "depthwise_conv", grid_dim, block_dim, args)

        if self.bias and bias is not None:
            # Add bias per channel (broadcast)
            out += bias.view(1, C, 1, 1)

        return out
